pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint amount) public {
        vm.assume(caller != address(0) && caller != address(c));
        vm.assume(amount > 0 && amount <= address(this).balance);
        vm.deal(caller, amount);
        vm.prank(caller);
        c.deposit{value: amount}();
        uint totalCredits = c.credit(caller);
        uint balanceBefore = address(c).balance;
        // Simulate a failed withdraw by making the caller a contract that rejects ETH
        vm.etch(caller, address(0).code); // empty code, so call reverts
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
