pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller1, address caller2, uint256 amount1, uint256 amount2) public {
        vm.assume(caller1 != address(0) && caller2 != address(0) && caller1 != caller2);
        vm.assume(amount1 > 0 && amount2 > 0);
        amount1 = bound(amount1, 0.001 ether, 100 ether);
        amount2 = bound(amount2, 0.001 ether, 100 ether);

        vm.deal(caller1, amount1);
        vm.prank(caller1);
        c.deposit{value: amount1}();

        vm.deal(caller2, amount2);
        vm.prank(caller2);
        c.deposit{value: amount2}();

        // Trigger a failed withdrawal (caller1 is a contract that rejects ether)
        // First, deploy a contract that rejects ether
        address rejector = address(new RejectEther());
        // Transfer caller1's credit to rejector by calling withdrawAll from rejector? No, better: make caller1 be a contract that rejects.
        // Simpler: use vm.prank to call withdrawAll from a contract address that rejects ether.
        vm.prank(address(rejector));
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        // Even if withdrawal fails (callResult false), the rule should hold.

        assertTrue(address(c).balance >= c.credit(caller1) + c.credit(caller2));
    }
}

contract RejectEther {
    receive() external payable {
        revert("reject");
    }
}

